import json
import sys


def solve(req):
    ebits = req['ebits']
    fbits = req['fbits']
    mode = req['mode']
    pairs = req.get('pairs') or []

    width = 1 + ebits + fbits
    mask = (1 << width) - 1
    F = 1 << fbits           # 2**fbits
    Eall = (1 << ebits) - 1  # all-ones exponent
    bias = (1 << (ebits - 1)) - 1
    emin = 1 - bias
    emax = Eall - 1 - bias
    fsmask = F - 1
    sshift = ebits + fbits   # position of the sign bit

    def dec(h):
        """-> (kind, sign, payload) where kind in {'inf','nan','fin'}.
        For 'nan' payload is True when signaling.
        For 'fin' payload is (mantissa, exponent) with value = sign*mant*2**exp.
        """
        v = int(h, 16) & mask
        s = (v >> sshift) & 1
        e = (v >> fbits) & Eall
        f = v & fsmask
        if e == Eall:
            if f:
                return ('nan', s, (f >> (fbits - 1)) == 0)
            return ('inf', s, None)
        if e == 0:
            return ('fin', s, (f, 1 - bias - fbits))
        return ('fin', s, (F + f, e - bias - fbits))

    def enc(s, e, f):
        return (s << sshift) | (e << fbits) | f

    # ---- inspect every operand / pair for exceptional conditions ----
    invalid = False
    nan_operand = False
    inf_signs = set()
    terms = []  # finite products: (sign, mantissa, exponent)

    for a_h, b_h in pairs:
        a = dec(a_h)
        b = dec(b_h)
        if a[0] == 'nan':
            nan_operand = True
            if a[2]:
                invalid = True
        if b[0] == 'nan':
            nan_operand = True
            if b[2]:
                invalid = True
        if a[0] == 'nan' or b[0] == 'nan':
            # a NaN pair contributes no infinite product and is not 0*inf
            continue
        a_inf = a[0] == 'inf'
        b_inf = b[0] == 'inf'
        if a_inf and b_inf:
            inf_signs.add(a[1] ^ b[1])
        elif a_inf or b_inf:
            fin = b if a_inf else a
            if fin[2][0] == 0:      # zero times infinity
                invalid = True
            else:
                inf_signs.add(a[1] ^ b[1])
        else:
            terms.append((a[1] ^ b[1], a[2][0] * b[2][0], a[2][1] + b[2][1]))

    if len(inf_signs) > 1:         # both +inf and -inf products
        invalid = True

    if nan_operand or invalid:
        canon = enc(0, Eall, 1 << (fbits - 1))
        return {'bits': '%x' % canon, 'flags': ['invalid'] if invalid else []}

    if inf_signs:
        (s,) = inf_signs
        return {'bits': '%x' % enc(s, Eall, 0), 'flags': []}

    # ---- exact finite summation ----
    if not terms:
        s = 1 if mode == 'RDN' else 0
        return {'bits': '%x' % enc(s, 0, 0), 'flags': []}

    m = min(t[2] for t in terms)
    total = 0
    for sg, mant, exp in terms:
        v = mant << (exp - m)
        total = total - v if sg else total + v

    if total == 0:
        neg_zero = all(sg == 1 and mant == 0 for sg, mant, _ in terms)
        s = 1 if (neg_zero or mode == 'RDN') else 0
        return {'bits': '%x' % enc(s, 0, 0), 'flags': []}

    s = 1 if total < 0 else 0
    M = -total if total < 0 else total
    L = M.bit_length() - 1 + m                 # floor(log2(x))
    qexp = emin - fbits
    if L - fbits > qexp:
        qexp = L - fbits
    # quantum q = 2**qexp ; x / q = M / 2**(qexp - m)

    d = qexp - m
    if d <= 0:
        y = M << (-d)
        exact = True
    else:
        div = 1 << d
        q_, r = divmod(M, div)
        if r == 0:
            y = q_
            exact = True
        else:
            exact = False
            half = div >> 1
            if mode == 'RNE':
                if r > half:
                    y = q_ + 1
                elif r < half:
                    y = q_
                else:
                    y = q_ + 1 if (q_ & 1) else q_
            elif mode == 'RNA':
                y = q_ + 1 if r >= half else q_
            elif mode == 'RTZ':
                y = q_
            elif mode == 'RUP':
                y = q_ + 1 if s == 0 else q_
            elif mode == 'RDN':
                y = q_ + 1 if s == 1 else q_
            else:
                raise ValueError('unknown mode: %r' % (mode,))

    # rounded magnitude = y * 2**qexp
    def rounded_exp():
        return y.bit_length() - 1 + qexp       # floor(log2(rounded)) or -inf if y==0

    if y != 0 and rounded_exp() >= emax + 1:
        # overflow: inf for nearest modes and the directed mode away from zero
        away = (mode in ('RNE', 'RNA')
                or (mode == 'RUP' and s == 0)
                or (mode == 'RDN' and s == 1))
        if away:
            bits = enc(s, Eall, 0)
        else:
            bits = enc(s, Eall - 1, F - 1)
        return {'bits': '%x' % bits, 'flags': ['overflow', 'inexact']}

    flags = []
    if not exact:
        flags.append('inexact')
        if y == 0 or rounded_exp() < emin:
            flags.append('underflow')

    if y == 0:
        bits = enc(s, 0, 0)                     # keeps the exact sign
    else:
        bl = rounded_exp()
        e = bl + bias
        if e < 1:
            # subnormal: value = f * 2**(emin - fbits)
            f = y << (qexp - (emin - fbits))
            bits = enc(s, 0, f)
        else:
            k = y.bit_length() - 1             # >= fbits here
            f = (y >> (k - fbits)) - F
            bits = enc(s, e, f)

    return {'bits': '%x' % bits, 'flags': flags}


def main():
    out = []
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        out.append(json.dumps(solve(json.loads(line))))
        print(out[-1], flush=False)
    sys.stdout.flush()


if __name__ == '__main__':
    main()
