"""Independent reference implementation (Fraction-based) for the finite path."""
from fractions import Fraction as Fr

def dec(h, ebits, fbits):
    width = 1 + ebits + fbits
    v = int(h, 16) & ((1 << width) - 1)
    s = v >> (ebits + fbits)
    e = (v >> fbits) & ((1 << ebits) - 1)
    f = v & ((1 << fbits) - 1)
    Eall = (1 << ebits) - 1
    bias = (1 << (ebits - 1)) - 1
    if e == Eall:
        if f == 0:
            return ('inf', s, None)
        return ('nan', s, (f >> (fbits - 1)) == 0)
    if e == 0:
        val = Fr(-1)**s * f * 2**(1 - bias - fbits)
    else:
        val = Fr(-1)**s * (2**fbits + f) * 2**(e - bias - fbits)
    return ('fin', s, val)

def floor_log2(x):  # x > 0 Fraction
    lo = None
    L = 0
    while (Fr(2)**L) <= x:
        L += 1
    return L - 1

def solve(req):
    ebits, fbits, mode = req['ebits'], req['fbits'], req['mode']
    pairs = req.get('pairs') or []
    Eall = (1 << ebits) - 1
    bias = (1 << (ebits - 1)) - 1
    F = 1 << fbits
    emin = 1 - bias
    emax = Eall - 1 - bias
    def enc(s, e, f):
        return '%x' % ((s << (ebits + fbits)) | (e << fbits) | f)
    invalid = False; nanop = False; infsigns = set(); prods = []
    for ah, bh in pairs:
        a = dec(ah, ebits, fbits); b = dec(bh, ebits, fbits)
        for o in (a, b):
            if o[0] == 'nan':
                nanop = True
                if o[2]: invalid = True
        if a[0] == 'nan' or b[0] == 'nan': continue
        if a[0] == 'inf' or b[0] == 'inf':
            if a[0] == 'inf' and b[0] == 'inf':
                infsigns.add(a[1] ^ b[1])
            else:
                fin = a if a[0] == 'fin' else b
                if fin[2] == 0: invalid = True
                else: infsigns.add(a[1] ^ b[1])
        else:
            v = a[2] * b[2]
            prods.append(v)
    if len(infsigns) > 1: invalid = True
    if nanop or invalid:
        return {'bits': enc(0, Eall, 1 << (fbits - 1)), 'flags': ['invalid'] if invalid else []}
    if infsigns:
        (s,) = infsigns
        return {'bits': enc(s, Eall, 0), 'flags': []}
    if not prods:
        return {'bits': enc(1 if mode == 'RDN' else 0, 0, 0), 'flags': []}
    total = sum(prods)
    if total == 0:
        neg = all(p == 0 and str(p).startswith('-') for p in prods)
        neg = all(p == 0 and p.numerator != 0 and p < 0 for p in prods)
        # a zero product is negative iff its value is -0: track signs separately
        s = 1 if (mode == 'RDN') else 0
        return {'bits': enc(s, 0, 0), 'flags': []}
    s = 1 if total < 0 else 0
    x = abs(total)
    L = floor_log2(x)
    qexp = max(emin - fbits, L - fbits)
    q = Fr(2)**qexp
    ratio = x / q
    fl = int(ratio)  # floor, ratio >= 0
    frac = ratio - fl
    if frac == 0:
        y = fl; exact = True
    else:
        exact = False
        half = Fr(1, 2)
        if mode == 'RNE':
            y = fl + 1 if frac > half else (fl if frac < half else (fl if fl % 2 == 0 else fl + 1))
        elif mode == 'RNA':
            y = fl + 1 if frac >= half else fl
        elif mode == 'RTZ':
            y = fl
        elif mode == 'RUP':
            y = fl + 1 if s == 0 else fl
        elif mode == 'RDN':
            y = fl + 1 if s == 1 else fl
    rounded = y * q
    if rounded >= Fr(2)**(emax + 1):
        away = mode in ('RNE', 'RNA') or (mode == 'RUP' and s == 0) or (mode == 'RDN' and s == 1)
        bits = enc(s, Eall, 0) if away else enc(s, Eall - 1, F - 1)
        return {'bits': bits, 'flags': ['overflow', 'inexact']}
    flags = []
