        flags.append('inexact')
        if rounded < Fr(2)**emin:
            flags.append('underflow')
    if rounded == 0:
        return {'bits': enc(s, 0, 0), 'flags': flags}
    Lp = floor_log2(rounded)
    e = Lp + bias
    if e < 1:
        f = rounded / Fr(2)**(emin - fbits)
        assert f.denominator == 1 and 0 < f < F
        return {'bits': enc(s, 0, int(f)), 'flags': flags}
    m = rounded / Fr(2)**(Lp - fbits)
    assert m.denominator == 1 and F <= m < 2 * F
    return {'bits': enc(s, e, int(m) - F), 'flags': flags}
